"""The shipped image constraints must match uv.lock (spec 042, FR-029).

If the sync test fails, run ``make constraints``.
"""

from __future__ import annotations

import shutil
from pathlib import Path

import pytest

from scripts import generate_constraints
from scripts.generate_constraints import (
    CONSTRAINTS_PATH,
    HEADER,
    OVERRIDES_PATH,
    is_stale,
    main,
    normalize,
    render_constraints,
    render_overrides,
)

UV_EXPORT = """\
# This file was autogenerated by uv via the following command:
zeta==2.0
alpha==1.0
alpha==1.0
colorama==0.4.6 ; sys_platform == 'win32'

"""


@pytest.mark.unit
def test_normalize_sorts_dedupes_and_drops_uv_comments() -> None:
    text = normalize(UV_EXPORT)

    assert text == (
        HEADER + "alpha==1.0\ncolorama==0.4.6 ; sys_platform == 'win32'\nzeta==2.0\n"
    )
    assert "autogenerated by uv" not in text


@pytest.mark.unit
def test_normalize_ignores_input_order() -> None:
    reversed_export = "\n".join(reversed(UV_EXPORT.splitlines()))

    assert normalize(reversed_export) == normalize(UV_EXPORT)


@pytest.mark.unit
def test_is_stale_detects_a_changed_pin() -> None:
    current = normalize("alpha==1.0\n")

    assert not is_stale(current, normalize("alpha==1.0\n"))
    assert is_stale(current, normalize("alpha==1.1\n"))
    assert is_stale(current, normalize("alpha==1.0\nbeta==1\n"))
    assert is_stale("", current)


@pytest.fixture
def fake_outputs(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> tuple[Path, Path]:
    """Point the generator at temp files with fixed rendered content."""
    constraints = tmp_path / "constraints.txt"
    overrides = tmp_path / "overrides.txt"
    monkeypatch.setattr(generate_constraints, "CONSTRAINTS_PATH", constraints)
    monkeypatch.setattr(generate_constraints, "OVERRIDES_PATH", overrides)
    monkeypatch.setattr(
        generate_constraints, "render_constraints", lambda: normalize("alpha==1.0\n")
    )
    monkeypatch.setattr(
        generate_constraints, "render_overrides", lambda: "pytz>=2024\n"
    )
    return constraints, overrides


@pytest.mark.unit
def test_check_fails_on_stale_constraints(
    fake_outputs: tuple[Path, Path], capsys: pytest.CaptureFixture[str]
) -> None:
    constraints, overrides = fake_outputs
    constraints.write_text(normalize("alpha==0.9\n"))
    overrides.write_text("pytz>=2024\n")

    assert main(["--check"]) == 1
    assert "make constraints" in capsys.readouterr().err


@pytest.mark.unit
def test_check_fails_on_stale_overrides(fake_outputs: tuple[Path, Path]) -> None:
    constraints, overrides = fake_outputs
    constraints.write_text(normalize("alpha==1.0\n"))
    overrides.write_text("pytz>=2020\n")

    assert main(["--check"]) == 1


@pytest.mark.unit
def test_check_fails_when_a_file_is_missing(fake_outputs: tuple[Path, Path]) -> None:
    assert main(["--check"]) == 1


@pytest.mark.unit
def test_check_passes_and_write_repairs(fake_outputs: tuple[Path, Path]) -> None:
    assert main(["--check"]) == 1
    assert main([]) == 0
    assert main(["--check"]) == 0


@pytest.mark.unit
@pytest.mark.skipif(shutil.which("uv") is None, reason="uv is not installed")
def test_committed_constraints_match_the_lock() -> None:
    assert (
        CONSTRAINTS_PATH.read_text() == render_constraints()
    ), "src/holodeck/deploy/constraints.txt is stale: run `make constraints`."


@pytest.mark.unit
def test_committed_overrides_match_pyproject() -> None:
    assert (
        OVERRIDES_PATH.read_text() == render_overrides()
    ), "src/holodeck/deploy/overrides.txt is stale: run `make constraints`."
    assert "pytz>=2024" in OVERRIDES_PATH.read_text().splitlines()


@pytest.mark.unit
def test_committed_constraints_pin_exactly_and_exclude_dev_tools() -> None:
    lines = [
        line
        for line in CONSTRAINTS_PATH.read_text().splitlines()
        if line and not line.startswith("#")
    ]
    names = {line.split("==")[0].lower() for line in lines}

    assert all("==" in line for line in lines)
    assert "holodeck-ai" not in names
    # Runtime packages that images install.
    assert {"pydantic", "claude-agent-sdk", "qdrant-client"} <= names
    # Documentation and release tooling are dev-only.
    assert not names & {"mkdocs", "mkdocs-material", "twine"}
